import type { Integration, IntegrationResult } from "../integration";

export type ChargeRequest = {
  /** Minor units — cents, not euros. See the note in `charge`. */
  amountMinor: number;
  currency: string;
  /** The patient this is for, so a mock can be deterministic per patient. */
  patient: string;
  /** What it is for, shown on a statement. */
  description: string;
  /**
   * The key that makes retrying safe.
   *
   * Generated by the caller, once, before the first attempt — never by
   * the adapter, which would generate a new one on the retry and defeat
   * the entire mechanism.
   */
  idempotencyKey: string;
  /**
   * A card the patient has already presented, as the gateway's own id.
   *
   * Optional because two of the three adapters do not need one: the desk
   * adapter records cash, and the mock simulates a terminal. A real
   * gateway cannot invent it — see `StripeGatewayAdapter` for why that is
   * a property of card payments rather than a gap in this code.
   */
  paymentMethod?: string | undefined;
  /** A test hook: mock gateways decline on demand. Ignored by real ones. */
  simulate?: "decline" | "network-error" | undefined;
};

export type ChargeResult = IntegrationResult<{
  /** True when this attempt matched a key the gateway had already seen. */
  replayed: boolean;
  settledAt: string;
}>;

export interface PaymentGateway extends Integration {
  /**
   * Take money.
   *
   * Amounts are integer minor units, never a float. `0.1 + 0.2` is
   * `0.30000000000000004`, and a rounding error in a currency column is
   * the kind of bug a bookkeeper finds six months later and nobody can
   * explain. Postgres holds `numeric` and is fine; the JavaScript in
   * between is not, so nothing here touches a float.
   */
  charge(request: ChargeRequest): Promise<ChargeResult>;

  /** Give it back. A refund is a charge with the sign flipped. */
  refund(reference: string, amountMinor: number, idempotencyKey: string): Promise<ChargeResult>;
}

/** Euros to cents, without ever holding a float. */
export function toMinor(amount: string | number): number {
  const text = typeof amount === "number" ? amount.toFixed(2) : amount.trim();
  const negative = text.startsWith("-");
  const [whole = "0", fraction = ""] = text.replace("-", "").split(".");
  const cents = Number(whole) * 100 + Number((fraction + "00").slice(0, 2));
  return negative ? -cents : cents;
}

export function fromMinor(minor: number): string {
  const sign = minor < 0 ? "-" : "";
  const abs = Math.abs(minor);
  return `${sign}${Math.floor(abs / 100)}.${String(abs % 100).padStart(2, "0")}`;
}
